begin;
create type public.consumer_subscription_status as enum('pending','active','past_due','cancelled','expired','failed');
create type public.consumer_entitlement_status as enum('inactive','active','suspended','expired');
create table public.consumer_subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id)on delete cascade,billing_customer_id uuid not null references public.payment_customers(id)on delete restrict,product_id uuid not null references public.payment_products(id)on delete restrict,price_id uuid not null references public.payment_prices(id)on delete restrict,provider text not null,environment public.payment_environment not null,provider_plan_reference text not null,provider_subscription_reference text not null,amount_minor bigint not null check(amount_minor>0),currency text not null check(currency='NGN'),billing_interval public.payment_billing_interval not null check(billing_interval='monthly'),status public.consumer_subscription_status not null default'pending',entitlement_status public.consumer_entitlement_status not null default'inactive',started_at timestamptz,current_period_start timestamptz,current_period_end timestamptz,next_billing_at timestamptz,cancel_at_period_end boolean not null default false,cancelled_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(provider,environment,provider_subscription_reference),check(current_period_end is null or current_period_start is null or current_period_end>current_period_start));
create unique index consumer_subscriptions_one_current_per_user_idx on public.consumer_subscriptions(user_id,product_id,environment)where status in('pending','active','past_due');
create index consumer_subscriptions_entitlement_idx on public.consumer_subscriptions(user_id,entitlement_status,status,current_period_end);
create table public.consumer_subscription_checkouts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id)on delete cascade,idempotency_key text not null unique,subscription_id uuid references public.consumer_subscriptions(id)on delete restrict,provider_reference text not null,created_at timestamptz not null default now(),unique(provider_reference));
create table public.consumer_subscription_events(id uuid primary key default gen_random_uuid(),provider text not null,environment public.payment_environment not null,provider_event_reference text not null,event_type text not null,subscription_id uuid references public.consumer_subscriptions(id)on delete restrict,processed_at timestamptz not null default now(),unique(provider,environment,provider_event_reference));
create trigger set_consumer_subscriptions_updated_at before update on public.consumer_subscriptions for each row execute function public.set_updated_at();
alter table public.consumer_subscriptions enable row level security;alter table public.consumer_subscription_checkouts enable row level security;alter table public.consumer_subscription_events enable row level security;
create policy consumer_subscriptions_own_read on public.consumer_subscriptions for select to authenticated using(user_id=(select auth.uid())or public.is_admin());
revoke insert,update,delete on public.consumer_subscriptions,public.consumer_subscription_checkouts,public.consumer_subscription_events from anon,authenticated;grant select on public.consumer_subscriptions to authenticated;
create or replace function public.has_active_consumer_subscription(p_user_id uuid)returns boolean language sql stable security definer set search_path=''as $$select p_user_id=(select auth.uid())and exists(select 1 from public.consumer_subscriptions s where s.user_id=p_user_id and s.status='active'and s.entitlement_status='active'and(s.current_period_end is null or s.current_period_end>now()))$$;
revoke all on function public.has_active_consumer_subscription(uuid)from public,anon;grant execute on function public.has_active_consumer_subscription(uuid)to authenticated,service_role;
commit;
